/**
 * Session list / event fetch for CLI (`sessions`, `session`, chat reattach).
 *
 * Customer-facing errors never include hosting URLs or infra jargon.
 */
import { isRecord } from "./is-record.js";
import { isSessionEvent } from "./json-value.js";
import { sanitizeCustomerError } from "./logs-client.js";
import { mergeRequestHeaders } from "./request-headers.js";
export async function listSessions(args) {
    return (await listSessionsWithSource(args)).sessions;
}
export async function listSessionsWithSource(args) {
    const baseUrl = args.baseUrl.replace(/\/$/, "");
    const fetchImpl = args.fetchImpl ?? fetch;
    const query = args.latest === true ? "?latest=1" : "";
    let resp;
    try {
        resp = await fetchImpl(`${baseUrl}/v1/sessions${query}`, {
            headers: mergeRequestHeaders(args.auth),
        });
    }
    catch (error) {
        throw new Error(sanitizeCustomerError(error instanceof Error ? error.message : "Could not list sessions."));
    }
    if (!resp.ok) {
        throw new Error(`Could not list sessions (HTTP ${resp.status}).`);
    }
    const parsedBody = await resp.json();
    const body = isRecord(parsedBody) ? parsedBody : {};
    const sessions = [];
    if (Array.isArray(body.sessions)) {
        for (const row of body.sessions) {
            const parsed = parseSessionSummary(row);
            if (parsed !== undefined) {
                sessions.push(parsed);
            }
        }
    }
    const source = body.source === "cursor-hosted" || body.source === "local" ? body.source : undefined;
    return source === undefined ? { sessions } : { sessions, source };
}
export async function fetchSessionEvents(args) {
    const baseUrl = args.baseUrl.replace(/\/$/, "");
    const fetchImpl = args.fetchImpl ?? fetch;
    const path = `/v1/session/${encodeURIComponent(args.sessionId)}/events`;
    try {
        const jsonResp = await fetchImpl(`${baseUrl}${path}?format=json`, {
            headers: mergeRequestHeaders(args.auth),
            signal: args.signal,
        });
        if (jsonResp.ok) {
            const body = await jsonResp.json();
            if (isRecord(body) && Array.isArray(body.events)) {
                return body.events.filter(isSessionEvent);
            }
        }
        else if (jsonResp.status === 404) {
            throw new Error(`Session ${args.sessionId} not found.`);
        }
        else if (jsonResp.status === 403) {
            throw new Error(`Session ${args.sessionId} is not readable by this caller.`);
        }
    }
    catch (error) {
        args.signal?.throwIfAborted();
        if (error instanceof Error && error.message.startsWith("Session ")) {
            throw error;
        }
        // Fall through to NDJSON.
    }
    try {
        const resp = await fetchImpl(`${baseUrl}${path}`, {
            headers: mergeRequestHeaders(args.auth),
            signal: args.signal,
        });
        if (resp.status === 404) {
            throw new Error(`Session ${args.sessionId} not found.`);
        }
        if (resp.status === 403) {
            throw new Error(`Session ${args.sessionId} is not readable by this caller.`);
        }
        if (!resp.ok) {
            throw new Error(`Could not fetch session events (HTTP ${resp.status}).`);
        }
        const text = await resp.text();
        const events = [];
        for (const line of text.split("\n")) {
            if (line.trim() === "") {
                continue;
            }
            try {
                const parsed = JSON.parse(line);
                if (isSessionEvent(parsed)) {
                    events.push(parsed);
                }
            }
            catch {
                // skip malformed lines
            }
        }
        return events;
    }
    catch (error) {
        args.signal?.throwIfAborted();
        if (error instanceof Error && error.message.startsWith("Session ")) {
            throw error;
        }
        if (error instanceof Error && error.message.startsWith("Could not fetch")) {
            throw new Error(sanitizeCustomerError(error.message));
        }
        throw new Error(sanitizeCustomerError(error instanceof Error ? error.message : "Could not fetch session events."));
    }
}
/**
 * Whole-session cost from `GET /v1/session/:id/cost`. Undefined when the
 * server cannot price the session or does not serve the route, so callers
 * can treat cost as optional.
 */
export async function fetchSessionCost(args) {
    const baseUrl = args.baseUrl.replace(/\/$/, "");
    const fetchImpl = args.fetchImpl ?? fetch;
    try {
        const resp = await fetchImpl(`${baseUrl}/v1/session/${encodeURIComponent(args.sessionId)}/cost`, { headers: mergeRequestHeaders(args.auth), signal: args.signal });
        if (!resp.ok) {
            return undefined;
        }
        const body = await resp.json();
        if (!isRecord(body) || typeof body.costUsd !== "number") {
            return undefined;
        }
        if (body.source !== "usage" && body.source !== "catalog") {
            return undefined;
        }
        const cost = isRecord(body.cost) ? body.cost : {};
        return {
            sessionId: typeof body.sessionId === "string" ? body.sessionId : args.sessionId,
            source: body.source,
            cost: {
                rawCostCents: typeof cost.rawCostCents === "number" ? cost.rawCostCents : 0,
                chargedCents: typeof cost.chargedCents === "number" ? cost.chargedCents : 0,
            },
            costUsd: body.costUsd,
            rawCostUsd: typeof body.rawCostUsd === "number" ? body.rawCostUsd : body.costUsd,
            model: typeof body.model === "string" ? body.model : undefined,
        };
    }
    catch {
        return undefined;
    }
}
/** Lenient parse so partial stubs / older servers still list by sessionId. */
function parseSessionSummary(value) {
    if (!isRecord(value)) {
        return undefined;
    }
    const row = value;
    if (typeof row.sessionId !== "string" || row.sessionId === "") {
        return undefined;
    }
    const continuationToken = typeof row.continuationToken === "string"
        ? row.continuationToken
        : row.continuationToken === null
            ? null
            : null;
    return {
        sessionId: row.sessionId,
        channelId: typeof row.channelId === "string" ? row.channelId : "",
        mode: row.mode === "task" ? "task" : "chat",
        title: typeof row.title === "string" ? row.title : undefined,
        turnCount: typeof row.turnCount === "number" ? row.turnCount : 0,
        running: row.running === true,
        queued: typeof row.queued === "boolean" ? row.queued : undefined,
        createdAt: typeof row.createdAt === "string" ? row.createdAt : "",
        updatedAt: typeof row.updatedAt === "string" ? row.updatedAt : "",
        dryRun: row.dryRun === true ? true : undefined,
        continuationToken,
        externalUrl: typeof row.externalUrl === "string" ? row.externalUrl : undefined,
        prUrl: typeof row.prUrl === "string" ? row.prUrl : undefined,
    };
}
/**
 * Pick the previous (most recently updated) followable session for
 * `resume` / `chat --resume` when no session id was passed.
 * Followable = has a non-empty continuation token (task sessions without
 * one are skipped).
 */
export function pickPreviousSession(sessions) {
    const followable = sessions.filter((s) => typeof s.continuationToken === "string" && s.continuationToken !== "");
    if (followable.length === 0) {
        return undefined;
    }
    return [...followable].sort((a, b) => b.updatedAt.localeCompare(a.updatedAt))[0];
}
/** Look up the most recently updated followable session id. */
export async function resolvePreviousSessionId(args) {
    const sessions = await listSessions({
        baseUrl: args.baseUrl,
        auth: args.auth,
        fetchImpl: args.fetchImpl,
    });
    return pickPreviousSession(sessions)?.sessionId;
}
/** Human label for {@link SessionListSource} in CLI output. */
export function formatSessionListSource(source) {
    return source === "cursor-hosted"
        ? "Listing from cursor-hosted storage (durable DB)."
        : "Listing from local session store.";
}
/** Format a sessions table (id, channel, mode, turns, running, updated). */
export function formatSessionsTable(sessions, options) {
    const sourceLine = options?.source === undefined ? "" : `${formatSessionListSource(options.source)}\n`;
    if (sessions.length === 0) {
        return `${sourceLine}No sessions.\n`;
    }
    const header = ["SESSION", "CHANNEL", "MODE", "TURNS", "RUNNING", "UPDATED"];
    const rows = sessions.map((s) => [
        s.sessionId,
        s.channelId,
        s.mode,
        String(s.turnCount),
        s.queued === true ? "queued" : s.running ? "yes" : "no",
        s.updatedAt,
    ]);
    return `${sourceLine}${renderTable(header, rows)}\n`;
}
export function formatHostedSessionsTable(sessions) {
    if (sessions.length === 0) {
        return "No sessions.\n";
    }
    const header = ["SESSION", "CHANNEL", "MODE", "PHASE", "CREATED", "LAST ACTIVITY"];
    const rows = sessions.map((s) => [
        s.sessionId,
        s.channelId,
        s.mode,
        s.phase,
        s.createdAt,
        s.lastActivityAt,
    ]);
    return `${renderTable(header, rows)}\n`;
}
function renderTable(header, rows) {
    const widths = header.map((h, i) => Math.max(h.length, ...rows.map((row) => (row[i] ?? "").length)));
    const renderRow = (row) => row
        .map((cell, i) => cell.padEnd(widths[i] ?? 0))
        .join("  ")
        .trimEnd();
    return [renderRow(header), ...rows.map(renderRow)].join("\n");
}
